BEGIN;
WITH x AS (SELECT school_type,field_name,branch_name,grade_level,schedule_variant,source_file_name,source_decision_no,min(source_page) p,max(source_page) p2 FROM official_course_schedule_catalog WHERE active AND school_type IN('MTAL','MESEM') AND source_page IS NOT NULL GROUP BY 1,2,3,4,5,6,7) UPDATE official_course_schedule_catalog s SET source_page=x.p,updated_at=now() FROM x WHERE s.active AND s.school_type IN('MTAL','MESEM') AND s.source_page IS NULL AND x.p=x.p2 AND x.school_type=s.school_type AND x.field_name IS NOT DISTINCT FROM s.field_name AND x.branch_name IS NOT DISTINCT FROM s.branch_name AND x.grade_level=s.grade_level AND x.schedule_variant=s.schedule_variant AND x.source_file_name IS NOT DISTINCT FROM s.source_file_name AND x.source_decision_no IS NOT DISTINCT FROM s.source_decision_no;
WITH x AS (SELECT school_type,field_name,branch_name,grade_level,schedule_variant,source_file_name,source_decision_no,min(source_page) p,max(source_page) p2 FROM official_course_schedule_catalog WHERE active AND school_type IN('MTAL','MESEM') AND source_page IS NOT NULL GROUP BY 1,2,3,4,5,6,7) UPDATE official_curriculum_profiles p SET source_page=x.p,updated_at=now() FROM x WHERE p.active AND p.school_type IN('MTAL','MESEM') AND p.source_page IS NULL AND x.p=x.p2 AND x.school_type=p.school_type AND x.field_name IS NOT DISTINCT FROM p.field_name AND x.branch_name IS NOT DISTINCT FROM p.branch_name AND x.grade_level=p.grade_level AND x.schedule_variant=p.schedule_variant AND x.source_file_name IS NOT DISTINCT FROM p.source_file_name AND x.source_decision_no IS NOT DISTINCT FROM p.source_decision_no;
WITH x AS (SELECT school_type,field_name,branch_name,grade_level,schedule_variant,source_file_name,source_decision_no,min(parsed_constraints::text) v,max(parsed_constraints::text) v2 FROM official_course_schedule_catalog WHERE active AND school_type IN('MTAL','MESEM') AND parsed_constraints<>'[]'::jsonb GROUP BY 1,2,3,4,5,6,7) UPDATE official_course_schedule_catalog s SET parsed_constraints=x.v::jsonb,updated_at=now() FROM x WHERE s.active AND s.school_type IN('MTAL','MESEM') AND s.parsed_constraints='[]'::jsonb AND x.v=x.v2 AND x.school_type=s.school_type AND x.field_name IS NOT DISTINCT FROM s.field_name AND x.branch_name IS NOT DISTINCT FROM s.branch_name AND x.grade_level=s.grade_level AND x.schedule_variant=s.schedule_variant AND x.source_file_name IS NOT DISTINCT FROM s.source_file_name AND x.source_decision_no IS NOT DISTINCT FROM s.source_decision_no;
COMMIT;